/* =============================================
   RedRoom Fitness — Design System
   ============================================= */

/* --- Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

/* --- Tokens --- */
:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.25);
  --bg: #141414;
  --bg-elevated: #1A1A1A;
  --bg-card: #1C1C1C;
  --bg-card-hover: #242424;
  --text: #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted: #777777;
  --border: #2A2A2A;
  --border-light: #333333;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif;
  --max-width: 1200px;
  --nav-height: 72px;
  --promo-height: 40px;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-height) + var(--promo-height));
}

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); font-weight: 700; }
h2 { font-size: clamp(2rem, 4vw, 3.2rem); font-weight: 600; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 500; }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  letter-spacing: 0.15em;
  color: var(--red);
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.section-heading {
  margin-bottom: 1rem;
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: 1.1rem;
  max-width: 640px;
  line-height: 1.7;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 4px;
  transition: all 0.25s ease;
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--text);
}

.btn-outline:hover {
  background: var(--text);
  color: var(--bg);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}

.btn-outline-red:hover {
  background: var(--red);
  color: #fff;
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.8rem;
}

.btn-lg {
  padding: 1.125rem 2.75rem;
  font-size: 1.05rem;
}

.btn-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* --- Top Promo Bar --- */
.promo-bar {
  background: var(--red);
  color: #fff;
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--promo-height);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
}

.promo-bar a {
  text-decoration: underline;
  font-weight: 600;
}

.promo-bar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: var(--promo-height);
  z-index: 999;
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-height);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-logo .logo-mark {
  width: 32px;
  height: 32px;
  background: var(--red);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-links a {
  padding: 0.5rem 0.85rem;
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  border-radius: 3px;
  transition: color 0.2s, background 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.highlight {
  color: var(--red);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.nav-utility .btn {
  font-size: 0.78rem;
  padding: 0.5rem 1.25rem;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
}

.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: all 0.3s ease;
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: calc(var(--nav-height) + var(--promo-height));
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg);
  z-index: 998;
  padding: 2rem;
  flex-direction: column;
  gap: 0.5rem;
  overflow-y: auto;
}

.mobile-nav.active {
  display: flex;
}

.mobile-nav a {
  display: block;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
  transition: color 0.2s;
}

.mobile-nav a:hover {
  color: var(--text);
}

.mobile-nav .mobile-utility {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.08) 0%, transparent 70%),
              linear-gradient(180deg, var(--bg) 0%, #1A1A1A 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255, 255, 255, 0.008) 2px,
      rgba(255, 255, 255, 0.008) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: 4rem 2rem;
}

.hero h1 {
  margin-bottom: 1.25rem;
  line-height: 1.05;
}

.hero .hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 2.5rem;
  line-height: 1.6;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero .btn-group {
  justify-content: center;
}

.hero-sm {
  min-height: 50vh;
}

.hero-sm .hero-content {
  padding: 3rem 2rem;
}

/* --- Sections --- */
.section {
  padding: 6rem 2rem;
}

.section-dark {
  background: var(--bg-elevated);
}

.section-red {
  background: var(--red);
  color: #fff;
}

.section-red .section-subtitle {
  color: rgba(255, 255, 255, 0.85);
}

.section-center {
  text-align: center;
}

.section-center .section-subtitle {
  margin-left: auto;
  margin-right: auto;
}

/* --- Community Promo --- */
.community-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.community-promo-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1A0000 0%, #330000 50%, #1A1A1A 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.community-promo-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(255,0,0,0.15) 0%, transparent 60%);
}

.community-promo-image .placeholder-text {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.08);
  text-transform: uppercase;
  letter-spacing: 0.2em;
}

.community-promo-text h2 {
  margin-bottom: 1.25rem;
}

.community-promo-text p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

/* --- Two Ways --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 3rem 2.5rem;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.way-card:hover::before {
  transform: scaleX(1);
}

.way-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}

.way-card .way-icon {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}

.way-card h3 {
  margin-bottom: 1rem;
}

.way-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* --- Studio Experience --- */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.studio-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #0A0000 0%, #1A0000 40%, #2A0000 100%);
  position: relative;
  overflow: hidden;
}

.studio-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 70% 30%, rgba(255,0,0,0.2) 0%, transparent 50%),
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 3px,
      rgba(255,255,255,0.01) 3px,
      rgba(255,255,255,0.01) 6px
    );
}

.studio-content h2 {
  margin-bottom: 1.25rem;
}

.studio-content p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

/* --- Free Trial CTA --- */
.trial-cta {
  text-align: center;
  padding: 5rem 2rem;
  background: linear-gradient(180deg, rgba(255,0,0,0.05) 0%, transparent 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.trial-cta h2 {
  margin-bottom: 1rem;
  font-size: clamp(2rem, 5vw, 3.5rem);
}

.trial-cta p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1.1rem;
}

/* --- Carousel --- */
.carousel-section {
  padding: 6rem 0;
}

.carousel {
  position: relative;
  overflow: hidden;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 2rem;
}

.carousel-slide-inner {
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.carousel-slide:nth-child(1) .carousel-slide-inner {
  background: linear-gradient(135deg, #1A0000 0%, #0D0000 50%, #1A1A1A 100%);
}

.carousel-slide:nth-child(2) .carousel-slide-inner {
  background: linear-gradient(135deg, #00001A 0%, #0A0A0A 50%, #1A0000 100%);
}

.carousel-slide:nth-child(3) .carousel-slide-inner {
  background: linear-gradient(135deg, #0A0A0A 0%, #1A0010 50%, #1A1A00 100%);
}

.carousel-slide:nth-child(4) .carousel-slide-inner {
  background: linear-gradient(135deg, #1A0A00 0%, #0A0A1A 50%, #001A0A 100%);
}

.carousel-slide:nth-child(5) .carousel-slide-inner {
  background: linear-gradient(135deg, #001A1A 0%, #1A1A00 50%, #1A000A 100%);
}

.slide-label {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.06);
  text-transform: uppercase;
  letter-spacing: 0.3em;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(20, 20, 20, 0.8);
  border: 1px solid var(--border-light);
  color: var(--text);
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn-prev {
  left: 2rem;
}

.carousel-btn-next {
  right: 2rem;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-light);
  cursor: pointer;
  transition: all 0.3s ease;
}

.carousel-dot.active {
  background: var(--red);
  transform: scale(1.3);
}

/* --- Toggle (Floor/Treadmill) --- */
.toggle-section {
  text-align: center;
}

.toggle-container {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 2.5rem;
}

.toggle-btn {
  padding: 0.875rem 2.5rem;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  transition: all 0.3s ease;
  cursor: pointer;
  border: none;
  background: transparent;
}

.toggle-btn.active {
  background: var(--red);
  color: #fff;
}

.toggle-content {
  display: none;
  max-width: 640px;
  margin: 0 auto;
  text-align: left;
}

.toggle-content.active {
  display: block;
  animation: fadeIn 0.35s ease;
}

.toggle-content h3 {
  margin-bottom: 1rem;
  color: var(--red);
}

.toggle-content p {
  color: var(--text-secondary);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* --- Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 2.5rem;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.8rem;
  color: var(--red);
  text-align: left;
  padding: 1rem 1.5rem;
  border-bottom: 2px solid var(--border);
}

.schedule-table tbody td {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
}

.schedule-table tbody tr {
  transition: background 0.2s;
}

.schedule-table tbody tr:hover {
  background: var(--bg-card);
}

.schedule-table .day {
  font-weight: 600;
  color: var(--text);
}

.schedule-table .focus-badge {
  display: inline-block;
  padding: 0.3rem 0.85rem;
  background: rgba(255, 0, 0, 0.1);
  border: 1px solid rgba(255, 0, 0, 0.2);
  border-radius: 3px;
  font-size: 0.85rem;
  color: var(--text);
}

.schedule-table .book-col {
  text-align: right;
}

/* --- Instructor Grid --- */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  margin-bottom: 3rem;
}

.filter-btn {
  padding: 0.6rem 1.5rem;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.25s ease;
}

.filter-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s ease;
}

.instructor-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.instructor-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--red), #990000);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: #fff;
}

.instructor-card h3 {
  margin-bottom: 0.25rem;
  font-size: 1.2rem;
}

.instructor-location {
  color: var(--red);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.25rem;
}

/* --- FAQ Accordion --- */
.accordion {
  max-width: 760px;
  margin: 0 auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: color 0.2s;
  background: none;
  border: none;
}

.accordion-header:hover {
  color: var(--red);
}

.accordion-icon {
  font-size: 1.5rem;
  transition: transform 0.3s ease;
  flex-shrink: 0;
  margin-left: 1rem;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
  color: var(--red);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.accordion-item.active .accordion-body {
  max-height: 300px;
}

.accordion-body-inner {
  padding: 0 0 1.5rem;
  color: var(--text-secondary);
  line-height: 1.8;
  font-size: 1rem;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
  margin-top: 3rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2.5rem 2rem;
  transition: all 0.3s ease;
}

.feature-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}

.feature-icon {
  font-size: 2rem;
  margin-bottom: 1.25rem;
  color: var(--red);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
}

.feature-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* --- Newsletter --- */
.newsletter {
  padding: 4rem 2rem;
  text-align: center;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
}

.newsletter h2 {
  margin-bottom: 0.75rem;
}

.newsletter p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1rem;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 480px;
  margin: 0 auto;
  position: relative;
}

.newsletter-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 0.95rem;
  transition: border-color 0.2s;
  outline: none;
}

.newsletter-input:focus {
  border-color: var(--red);
}

.newsletter-input.error {
  border-color: var(--red);
}

.newsletter-message {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5em;
}

.newsletter-message.success {
  color: #4CAF50;
}

.newsletter-message.error {
  color: var(--red);
}

/* --- Footer --- */
.footer {
  background: var(--bg);
  border-top: 1px solid var(--border);
  padding: 5rem 2rem 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-brand h3 {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.9rem;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 0.35rem 0;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--text);
}

.country-selector {
  position: relative;
  display: inline-block;
  margin-top: 1.5rem;
}

.country-selector-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color 0.2s;
}

.country-selector-btn:hover {
  border-color: var(--text-muted);
}

.country-selector-btn .arrow {
  font-size: 0.7rem;
  transition: transform 0.2s;
}

.country-selector.open .country-selector-btn .arrow {
  transform: rotate(180deg);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 0.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  min-width: 160px;
  display: none;
  z-index: 10;
}

.country-selector.open .country-dropdown {
  display: block;
  animation: fadeIn 0.2s ease;
}

.country-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.6rem 1rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: all 0.2s;
}

.country-dropdown button:hover {
  background: var(--bg-card-hover);
  color: var(--text);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 3rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
}

.footer-bottom-links a {
  color: var(--text-muted);
  font-size: 0.8rem;
  transition: color 0.2s;
}

.footer-bottom-links a:hover {
  color: var(--text);
}

/* --- Page Hero Variations --- */
.page-hero {
  min-height: 40vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.06) 0%, transparent 60%),
              var(--bg);
}

.page-hero h1 {
  margin-bottom: 1rem;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeInUp 0.6s ease forwards;
}

/* --- Utility --- */
.text-red { color: var(--red); }
.text-center { text-align: center; }
.mt-1 { margin-top: 1rem; }
.mt-2 { margin-top: 2rem; }
.mt-3 { margin-top: 3rem; }
.mb-1 { margin-bottom: 1rem; }
.mb-2 { margin-bottom: 2rem; }

/* --- Method Overview --- */
.method-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.method-content p {
  color: var(--text-secondary);
  font-size: 1.15rem;
  line-height: 1.9;
}

/* --- Unlimited Banner --- */
.unlimited-banner {
  background: linear-gradient(135deg, rgba(255,0,0,0.1) 0%, rgba(255,0,0,0.02) 100%);
  border: 1px solid rgba(255,0,0,0.15);
  padding: 3rem;
  text-align: center;
  max-width: 700px;
  margin: 3rem auto 0;
}

.unlimited-banner h3 {
  color: var(--red);
  margin-bottom: 0.75rem;
}

.unlimited-banner p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-utility {
    display: none;
  }

  .nav-toggle {
    display: flex;
  }

  .hero {
    min-height: 70vh;
  }

  .community-promo,
  .studio-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .community-promo-image {
    order: -1;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .section {
    padding: 3.5rem 1.5rem;
  }

  .hero-content {
    padding: 2.5rem 1.5rem;
  }

  .carousel-btn {
    width: 40px;
    height: 40px;
    font-size: 1rem;
  }

  .carousel-btn-prev { left: 0.5rem; }
  .carousel-btn-next { right: 0.5rem; }

  .instructor-grid {
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.85rem;
  }

  .schedule-table thead th,
  .schedule-table tbody td {
    padding: 0.875rem 1rem;
    font-size: 0.85rem;
  }
}

@media (max-width: 480px) {
  .btn-group {
    flex-direction: column;
    align-items: center;
  }

  .btn-group .btn {
    width: 100%;
  }

  .carousel-slide-inner {
    aspect-ratio: 4/3;
  }
}

/* =============================================
   RedRoom Fitness — Design System
   ============================================= */

/* --- Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

/* --- Tokens --- */
:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.25);
  --bg: #141414;
  --bg-elevated: #1A1A1A;
  --bg-card: #1C1C1C;
  --bg-card-hover: #242424;
  --text: #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted: #777777;
  --border: #2A2A2A;
  --border-light: #333333;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif;
  --max-width: 1200px;
  --nav-height: 72px;
  --promo-height: 40px;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-height) + var(--promo-height));
}

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); font-weight: 700; }
h2 { font-size: clamp(2rem, 4vw, 3.2rem); font-weight: 600; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 500; }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  letter-spacing: 0.15em;
  color: var(--red);
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.section-heading {
  margin-bottom: 1rem;
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: 1.1rem;
  max-width: 640px;
  line-height: 1.7;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 4px;
  transition: all 0.25s ease;
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--text);
}

.btn-outline:hover {
  background: var(--text);
  color: var(--bg);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}

.btn-outline-red:hover {
  background: var(--red);
  color: #fff;
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.8rem;
}

.btn-lg {
  padding: 1.125rem 2.75rem;
  font-size: 1.05rem;
}

.btn-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* --- Top Promo Bar --- */
.promo-bar {
  background: var(--red);
  color: #fff;
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--promo-height);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
}

.promo-bar a {
  text-decoration: underline;
  font-weight: 600;
}

.promo-bar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: var(--promo-height);
  z-index: 999;
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-height);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-logo .logo-mark {
  width: 32px;
  height: 32px;
  background: var(--red);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-links a {
  padding: 0.5rem 0.85rem;
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  border-radius: 3px;
  transition: color 0.2s, background 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.highlight {
  color: var(--red);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.nav-utility .btn {
  font-size: 0.78rem;
  padding: 0.5rem 1.25rem;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
}

.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: all 0.3s ease;
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: calc(var(--nav-height) + var(--promo-height));
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg);
  z-index: 998;
  padding: 2rem;
  flex-direction: column;
  gap: 0.5rem;
  overflow-y: auto;
}

.mobile-nav.active {
  display: flex;
}

.mobile-nav a {
  display: block;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
  transition: color 0.2s;
}

.mobile-nav a:hover {
  color: var(--text);
}

.mobile-nav .mobile-utility {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.08) 0%, transparent 70%),
              linear-gradient(180deg, var(--bg) 0%, #1A1A1A 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255, 255, 255, 0.008) 2px,
      rgba(255, 255, 255, 0.008) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: 4rem 2rem;
}

.hero h1 {
  margin-bottom: 1.25rem;
  line-height: 1.05;
}

.hero .hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 2.5rem;
  line-height: 1.6;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero .btn-group {
  justify-content: center;
}

.hero-sm {
  min-height: 50vh;
}

.hero-sm .hero-content {
  padding: 3rem 2rem;
}

/* --- Sections --- */
.section {
  padding: 6rem 2rem;
}

.section-dark {
  background: var(--bg-elevated);
}

.section-red {
  background: var(--red);
  color: #fff;
}

.section-red .section-subtitle {
  color: rgba(255, 255, 255, 0.85);
}

.section-center {
  text-align: center;
}

.section-center .section-subtitle {
  margin-left: auto;
  margin-right: auto;
}

/* --- Community Promo --- */
.community-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.community-promo-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1A0000 0%, #330000 50%, #1A1A1A 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.community-promo-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(255,0,0,0.15) 0%, transparent 60%);
}

.community-promo-image .placeholder-text {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.08);
  text-transform: uppercase;
  letter-spacing: 0.2em;
}

.community-promo-text h2 {
  margin-bottom: 1.25rem;
}

.community-promo-text p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

/* --- Two Ways --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 3rem 2.5rem;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.way-card:hover::before {
  transform: scaleX(1);
}

.way-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}

.way-card .way-icon {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}

.way-card h3 {
  margin-bottom: 1rem;
}

.way-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* --- Studio Experience --- */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.studio-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #0A0000 0%, #1A0000 40%, #2A0000 100%);
  position: relative;
  overflow: hidden;
}

.studio-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 70% 30%, rgba(255,0,0,0.2) 0%, transparent 50%),
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 3px,
      rgba(255,255,255,0.01) 3px,
      rgba(255,255,255,0.01) 6px
    );
}

.studio-content h2 {
  margin-bottom: 1.25rem;
}

.studio-content p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

/* --- Free Trial CTA --- */
.trial-cta {
  text-align: center;
  padding: 5rem 2rem;
  background: linear-gradient(180deg, rgba(255,0,0,0.05) 0%, transparent 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.trial-cta h2 {
  margin-bottom: 1rem;
  font-size: clamp(2rem, 5vw, 3.5rem);
}

.trial-cta p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1.1rem;
}

/* --- Carousel --- */
.carousel-section {
  padding: 6rem 0;
}

.carousel {
  position: relative;
  overflow: hidden;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 2rem;
}

.carousel-slide-inner {
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.carousel-slide:nth-child(1) .carousel-slide-inner {
  background: linear-gradient(135deg, #1A0000 0%, #0D0000 50%, #1A1A1A 100%);
}

.carousel-slide:nth-child(2) .carousel-slide-inner {
  background: linear-gradient(135deg, #00001A 0%, #0A0A0A 50%, #1A0000 100%);
}

.carousel-slide:nth-child(3) .carousel-slide-inner {
  background: linear-gradient(135deg, #0A0A0A 0%, #1A0010 50%, #1A1A00 100%);
}

.carousel-slide:nth-child(4) .carousel-slide-inner {
  background: linear-gradient(135deg, #1A0A00 0%, #0A0A1A 50%, #001A0A 100%);
}

.carousel-slide:nth-child(5) .carousel-slide-inner {
  background: linear-gradient(135deg, #001A1A 0%, #1A1A00 50%, #1A000A 100%);
}

.slide-label {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.06);
  text-transform: uppercase;
  letter-spacing: 0.3em;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(20, 20, 20, 0.8);
  border: 1px solid var(--border-light);
  color: var(--text);
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn-prev {
  left: 2rem;
}

.carousel-btn-next {
  right: 2rem;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-light);
  cursor: pointer;
  transition: all 0.3s ease;
}

.carousel-dot.active {
  background: var(--red);
  transform: scale(1.3);
}

/* --- Toggle (Floor/Treadmill) --- */
.toggle-section {
  text-align: center;
}

.toggle-container {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 2.5rem;
}

.toggle-btn {
  padding: 0.875rem 2.5rem;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  transition: all 0.3s ease;
  cursor: pointer;
  border: none;
  background: transparent;
}

.toggle-btn.active {
  background: var(--red);
  color: #fff;
}

.toggle-content {
  display: none;
  max-width: 640px;
  margin: 0 auto;
  text-align: left;
}

.toggle-content.active {
  display: block;
  animation: fadeIn 0.35s ease;
}

.toggle-content h3 {
  margin-bottom: 1rem;
  color: var(--red);
}

.toggle-content p {
  color: var(--text-secondary);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* --- Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 2.5rem;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.8rem;
  color: var(--red);
  text-align: left;
  padding: 1rem 1.5rem;
  border-bottom: 2px solid var(--border);
}

.schedule-table tbody td {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
}

.schedule-table tbody tr {
  transition: background 0.2s;
}

.schedule-table tbody tr:hover {
  background: var(--bg-card);
}

.schedule-table .day {
  font-weight: 600;
  color: var(--text);
}

.schedule-table .focus-badge {
  display: inline-block;
  padding: 0.3rem 0.85rem;
  background: rgba(255, 0, 0, 0.1);
  border: 1px solid rgba(255, 0, 0, 0.2);
  border-radius: 3px;
  font-size: 0.85rem;
  color: var(--text);
}

.schedule-table .book-col {
  text-align: right;
}

/* --- Instructor Grid --- */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  margin-bottom: 3rem;
}

.filter-btn {
  padding: 0.6rem 1.5rem;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.25s ease;
}

.filter-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s ease;
}

.instructor-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.instructor-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--red), #990000);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: #fff;
}

.instructor-card h3 {
  margin-bottom: 0.25rem;
  font-size: 1.2rem;
}

.instructor-location {
  color: var(--red);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.25rem;
}

/* --- FAQ Accordion --- */
.accordion {
  max-width: 760px;
  margin: 0 auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: color 0.2s;
  background: none;
  border: none;
}

.accordion-header:hover {
  color: var(--red);
}

.accordion-icon {
  font-size: 1.5rem;
  transition: transform 0.3s ease;
  flex-shrink: 0;
  margin-left: 1rem;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
  color: var(--red);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.accordion-item.active .accordion-body {
  max-height: 300px;
}

.accordion-body-inner {
  padding: 0 0 1.5rem;
  color: var(--text-secondary);
  line-height: 1.8;
  font-size: 1rem;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
  margin-top: 3rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2.5rem 2rem;
  transition: all 0.3s ease;
}

.feature-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}

.feature-icon {
  font-size: 2rem;
  margin-bottom: 1.25rem;
  color: var(--red);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
}

.feature-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* --- Newsletter --- */
.newsletter {
  padding: 4rem 2rem;
  text-align: center;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
}

.newsletter h2 {
  margin-bottom: 0.75rem;
}

.newsletter p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1rem;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 480px;
  margin: 0 auto;
  position: relative;
}

.newsletter-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 0.95rem;
  transition: border-color 0.2s;
  outline: none;
}

.newsletter-input:focus {
  border-color: var(--red);
}

.newsletter-input.error {
  border-color: var(--red);
}

.newsletter-message {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5em;
}

.newsletter-message.success {
  color: #4CAF50;
}

.newsletter-message.error {
  color: var(--red);
}

/* --- Footer --- */
.footer {
  background: var(--bg);
  border-top: 1px solid var(--border);
  padding: 5rem 2rem 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-brand h3 {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.9rem;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 0.35rem 0;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--text);
}

.country-selector {
  position: relative;
  display: inline-block;
  margin-top: 1.5rem;
}

.country-selector-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color 0.2s;
}

.country-selector-btn:hover {
  border-color: var(--text-muted);
}

.country-selector-btn .arrow {
  font-size: 0.7rem;
  transition: transform 0.2s;
}

.country-selector.open .country-selector-btn .arrow {
  transform: rotate(180deg);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 0.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  min-width: 160px;
  display: none;
  z-index: 10;
}

.country-selector.open .country-dropdown {
  display: block;
  animation: fadeIn 0.2s ease;
}

.country-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.6rem 1rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: all 0.2s;
}

.country-dropdown button:hover {
  background: var(--bg-card-hover);
  color: var(--text);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 3rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
}

.footer-bottom-links a {
  color: var(--text-muted);
  font-size: 0.8rem;
  transition: color 0.2s;
}

.footer-bottom-links a:hover {
  color: var(--text);
}

/* --- Page Hero Variations --- */
.page-hero {
  min-height: 40vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.06) 0%, transparent 60%),
              var(--bg);
}

.page-hero h1 {
  margin-bottom: 1rem;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeInUp 0.6s ease forwards;
}

/* --- Utility --- */
.text-red { color: var(--red); }
.text-center { text-align: center; }
.mt-1 { margin-top: 1rem; }
.mt-2 { margin-top: 2rem; }
.mt-3 { margin-top: 3rem; }
.mb-1 { margin-bottom: 1rem; }
.mb-2 { margin-bottom: 2rem; }

/* --- Method Overview --- */
.method-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.method-content p {
  color: var(--text-secondary);
  font-size: 1.15rem;
  line-height: 1.9;
}

/* --- Unlimited Banner --- */
.unlimited-banner {
  background: linear-gradient(135deg, rgba(255,0,0,0.1) 0%, rgba(255,0,0,0.02) 100%);
  border: 1px solid rgba(255,0,0,0.15);
  padding: 3rem;
  text-align: center;
  max-width: 700px;
  margin: 3rem auto 0;
}

.unlimited-banner h3 {
  color: var(--red);
  margin-bottom: 0.75rem;
}

.unlimited-banner p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-utility {
    display: none;
  }

  .nav-toggle {
    display: flex;
  }

  .hero {
    min-height: 70vh;
  }

  .community-promo,
  .studio-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .community-promo-image {
    order: -1;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .section {
    padding: 3.5rem 1.5rem;
  }

  .hero-content {
    padding: 2.5rem 1.5rem;
  }

  .carousel-btn {
    width: 40px;
    height: 40px;
    font-size: 1rem;
  }

  .carousel-btn-prev { left: 0.5rem; }
  .carousel-btn-next { right: 0.5rem; }

  .instructor-grid {
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.85rem;
  }

  .schedule-table thead th,
  .schedule-table tbody td {
    padding: 0.875rem 1rem;
    font-size: 0.85rem;
  }
}

@media (max-width: 480px) {
  .btn-group {
    flex-direction: column;
    align-items: center;
  }

  .btn-group .btn {
    width: 100%;
  }

  .carousel-slide-inner {
    aspect-ratio: 4/3;
  }
}

raw_arguments.content:
/* =============================================
   RedRoom Fitness — Design System
   ============================================= */

/* --- Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

/* --- Tokens --- */
:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.25);
  --bg: #141414;
  --bg-elevated: #1A1A1A;
  --bg-card: #1C1C1C;
  --bg-card-hover: #242424;
  --text: #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted: #777777;
  --border: #2A2A2A;
  --border-light: #333333;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif;
  --max-width: 1200px;
  --nav-height: 72px;
  --promo-height: 40px;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-height) + var(--promo-height));
}

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); font-weight: 700; }
h2 { font-size: clamp(2rem, 4vw, 3.2rem); font-weight: 600; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 500; }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  letter-spacing: 0.15em;
  color: var(--red);
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.section-heading {
  margin-bottom: 1rem;
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: 1.1rem;
  max-width: 640px;
  line-height: 1.7;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 4px;
  transition: all 0.25s ease;
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--text);
}

.btn-outline:hover {
  background: var(--text);
  color: var(--bg);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}

.btn-outline-red:hover {
  background: var(--red);
  color: #fff;
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.8rem;
}

.btn-lg {
  padding: 1.125rem 2.75rem;
  font-size: 1.05rem;
}

.btn-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* --- Top Promo Bar --- */
.promo-bar {
  background: var(--red);
  color: #fff;
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--promo-height);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
}

.promo-bar a {
  text-decoration: underline;
  font-weight: 600;
}

.promo-bar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: var(--promo-height);
  z-index: 999;
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-height);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-logo .logo-mark {
  width: 32px;
  height: 32px;
  background: var(--red);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-links a {
  padding: 0.5rem 0.85rem;
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  border-radius: 3px;
  transition: color 0.2s, background 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.highlight {
  color: var(--red);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.nav-utility .btn {
  font-size: 0.78rem;
  padding: 0.5rem 1.25rem;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
}

.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: all 0.3s ease;
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: calc(var(--nav-height) + var(--promo-height));
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg);
  z-index: 998;
  padding: 2rem;
  flex-direction: column;
  gap: 0.5rem;
  overflow-y: auto;
}

.mobile-nav.active {
  display: flex;
}

.mobile-nav a {
  display: block;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
  transition: color 0.2s;
}

.mobile-nav a:hover {
  color: var(--text);
}

.mobile-nav .mobile-utility {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.08) 0%, transparent 70%),
              linear-gradient(180deg, var(--bg) 0%, #1A1A1A 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255, 255, 255, 0.008) 2px,
      rgba(255, 255, 255, 0.008) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: 4rem 2rem;
}

.hero h1 {
  margin-bottom: 1.25rem;
  line-height: 1.05;
}

.hero .hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 2.5rem;
  line-height: 1.6;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero .btn-group {
  justify-content: center;
}

.hero-sm {
  min-height: 50vh;
}

.hero-sm .hero-content {
  padding: 3rem 2rem;
}

/* --- Sections --- */
.section {
  padding: 6rem 2rem;
}

.section-dark {
  background: var(--bg-elevated);
}

.section-red {
  background: var(--red);
  color: #fff;
}

.section-red .section-subtitle {
  color: rgba(255, 255, 255, 0.85);
}

.section-center {
  text-align: center;
}

.section-center .section-subtitle {
  margin-left: auto;
  margin-right: auto;
}

/* --- Community Promo --- */
.community-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.community-promo-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1A0000 0%, #330000 50%, #1A1A1A 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.community-promo-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(255,0,0,0.15) 0%, transparent 60%);
}

.community-promo-image .placeholder-text {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.08);
  text-transform: uppercase;
  letter-spacing: 0.2em;
}

.community-promo-text h2 {
  margin-bottom: 1.25rem;
}

.community-promo-text p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

/* --- Two Ways --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 3rem 2.5rem;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.way-card:hover::before {
  transform: scaleX(1);
}

.way-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}

.way-card .way-icon {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}

.way-card h3 {
  margin-bottom: 1rem;
}

.way-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* --- Studio Experience --- */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.studio-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #0A0000 0%, #1A0000 40%, #2A0000 100%);
  position: relative;
  overflow: hidden;
}

.studio-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 70% 30%, rgba(255,0,0,0.2) 0%, transparent 50%),
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 3px,
      rgba(255,255,255,0.01) 3px,
      rgba(255,255,255,0.01) 6px
    );
}

.studio-content h2 {
  margin-bottom: 1.25rem;
}

.studio-content p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

/* --- Free Trial CTA --- */
.trial-cta {
  text-align: center;
  padding: 5rem 2rem;
  background: linear-gradient(180deg, rgba(255,0,0,0.05) 0%, transparent 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.trial-cta h2 {
  margin-bottom: 1rem;
  font-size: clamp(2rem, 5vw, 3.5rem);
}

.trial-cta p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1.1rem;
}

/* --- Carousel --- */
.carousel-section {
  padding: 6rem 0;
}

.carousel {
  position: relative;
  overflow: hidden;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 2rem;
}

.carousel-slide-inner {
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.carousel-slide:nth-child(1) .carousel-slide-inner {
  background: linear-gradient(135deg, #1A0000 0%, #0D0000 50%, #1A1A1A 100%);
}

.carousel-slide:nth-child(2) .carousel-slide-inner {
  background: linear-gradient(135deg, #00001A 0%, #0A0A0A 50%, #1A0000 100%);
}

.carousel-slide:nth-child(3) .carousel-slide-inner {
  background: linear-gradient(135deg, #0A0A0A 0%, #1A0010 50%, #1A1A00 100%);
}

.carousel-slide:nth-child(4) .carousel-slide-inner {
  background: linear-gradient(135deg, #1A0A00 0%, #0A0A1A 50%, #001A0A 100%);
}

.carousel-slide:nth-child(5) .carousel-slide-inner {
  background: linear-gradient(135deg, #001A1A 0%, #1A1A00 50%, #1A000A 100%);
}

.slide-label {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.06);
  text-transform: uppercase;
  letter-spacing: 0.3em;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(20, 20, 20, 0.8);
  border: 1px solid var(--border-light);
  color: var(--text);
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn-prev {
  left: 2rem;
}

.carousel-btn-next {
  right: 2rem;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-light);
  cursor: pointer;
  transition: all 0.3s ease;
}

.carousel-dot.active {
  background: var(--red);
  transform: scale(1.3);
}

/* --- Toggle (Floor/Treadmill) --- */
.toggle-section {
  text-align: center;
}

.toggle-container {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 2.5rem;
}

.toggle-btn {
  padding: 0.875rem 2.5rem;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  transition: all 0.3s ease;
  cursor: pointer;
  border: none;
  background: transparent;
}

.toggle-btn.active {
  background: var(--red);
  color: #fff;
}

.toggle-content {
  display: none;
  max-width: 640px;
  margin: 0 auto;
  text-align: left;
}

.toggle-content.active {
  display: block;
  animation: fadeIn 0.35s ease;
}

.toggle-content h3 {
  margin-bottom: 1rem;
  color: var(--red);
}

.toggle-content p {
  color: var(--text-secondary);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* --- Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 2.5rem;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.8rem;
  color: var(--red);
  text-align: left;
  padding: 1rem 1.5rem;
  border-bottom: 2px solid var(--border);
}

.schedule-table tbody td {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
}

.schedule-table tbody tr {
  transition: background 0.2s;
}

.schedule-table tbody tr:hover {
  background: var(--bg-card);
}

.schedule-table .day {
  font-weight: 600;
  color: var(--text);
}

.schedule-table .focus-badge {
  display: inline-block;
  padding: 0.3rem 0.85rem;
  background: rgba(255, 0, 0, 0.1);
  border: 1px solid rgba(255, 0, 0, 0.2);
  border-radius: 3px;
  font-size: 0.85rem;
  color: var(--text);
}

.schedule-table .book-col {
  text-align: right;
}

/* --- Instructor Grid --- */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  margin-bottom: 3rem;
}

.filter-btn {
  padding: 0.6rem 1.5rem;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.25s ease;
}

.filter-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s ease;
}

.instructor-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.instructor-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--red), #990000);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: #fff;
}

.instructor-card h3 {
  margin-bottom: 0.25rem;
  font-size: 1.2rem;
}

.instructor-location {
  color: var(--red);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.25rem;
}

/* --- FAQ Accordion --- */
.accordion {
  max-width: 760px;
  margin: 0 auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: color 0.2s;
  background: none;
  border: none;
}

.accordion-header:hover {
  color: var(--red);
}

.accordion-icon {
  font-size: 1.5rem;
  transition: transform 0.3s ease;
  flex-shrink: 0;
  margin-left: 1rem;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
  color: var(--red);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.accordion-item.active .accordion-body {
  max-height: 300px;
}

.accordion-body-inner {
  padding: 0 0 1.5rem;
  color: var(--text-secondary);
  line-height: 1.8;
  font-size: 1rem;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
  margin-top: 3rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2.5rem 2rem;
  transition: all 0.3s ease;
}

.feature-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}

.feature-icon {
  font-size: 2rem;
  margin-bottom: 1.25rem;
  color: var(--red);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
}

.feature-card p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* --- Newsletter --- */
.newsletter {
  padding: 4rem 2rem;
  text-align: center;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
}

.newsletter h2 {
  margin-bottom: 0.75rem;
}

.newsletter p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1rem;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 480px;
  margin: 0 auto;
  position: relative;
}

.newsletter-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 0.95rem;
  transition: border-color 0.2s;
  outline: none;
}

.newsletter-input:focus {
  border-color: var(--red);
}

.newsletter-input.error {
  border-color: var(--red);
}

.newsletter-message {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5em;
}

.newsletter-message.success {
  color: #4CAF50;
}

.newsletter-message.error {
  color: var(--red);
}

/* --- Footer --- */
.footer {
  background: var(--bg);
  border-top: 1px solid var(--border);
  padding: 5rem 2rem 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-brand h3 {
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.9rem;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 0.35rem 0;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--text);
}

.country-selector {
  position: relative;
  display: inline-block;
  margin-top: 1.5rem;
}

.country-selector-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color 0.2s;
}

.country-selector-btn:hover {
  border-color: var(--text-muted);
}

.country-selector-btn .arrow {
  font-size: 0.7rem;
  transition: transform 0.2s;
}

.country-selector.open .country-selector-btn .arrow {
  transform: rotate(180deg);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 0.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  min-width: 160px;
  display: none;
  z-index: 10;
}

.country-selector.open .country-dropdown {
  display: block;
  animation: fadeIn 0.2s ease;
}

.country-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.6rem 1rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: all 0.2s;
}

.country-dropdown button:hover {
  background: var(--bg-card-hover);
  color: var(--text);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 3rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
}

.footer-bottom-links a {
  color: var(--text-muted);
  font-size: 0.8rem;
  transition: color 0.2s;
}

.footer-bottom-links a:hover {
  color: var(--text);
}

/* --- Page Hero Variations --- */
.page-hero {
  min-height: 40vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.06) 0%, transparent 60%),
              var(--bg);
}

.page-hero h1 {
  margin-bottom: 1rem;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeInUp 0.6s ease forwards;
}

/* --- Utility --- */
.text-red { color: var(--red); }
.text-center { text-align: center; }
.mt-1 { margin-top: 1rem; }
.mt-2 { margin-top: 2rem; }
.mt-3 { margin-top: 3rem; }
.mb-1 { margin-bottom: 1rem; }
.mb-2 { margin-bottom: 2rem; }

/* --- Method Overview --- */
.method-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.method-content p {
  color: var(--text-secondary);
  font-size: 1.15rem;
  line-height: 1.9;
}

/* --- Unlimited Banner --- */
.unlimited-banner {
  background: linear-gradient(135deg, rgba(255,0,0,0.1) 0%, rgba(255,0,0,0.02) 100%);
  border: 1px solid rgba(255,0,0,0.15);
  padding: 3rem;
  text-align: center;
  max-width: 700px;
  margin: 3rem auto 0;
}

.unlimited-banner h3 {
  color: var(--red);
  margin-bottom: 0.75rem;
}

.unlimited-banner p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-utility {
    display: none;
  }

  .nav-toggle {
    display: flex;
  }

  .hero {
    min-height: 70vh;
  }

  .community-promo,
  .studio-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .community-promo-image {
    order: -1;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .section {
    padding: 3.5rem 1.5rem;
  }

  .hero-content {
    padding: 2.5rem 1.5rem;
  }

  .carousel-btn {
    width: 40px;
    height: 40px;
    font-size: 1rem;
  }

  .carousel-btn-prev { left: 0.5rem; }
  .carousel-btn-next { right: 0.5rem; }

  .instructor-grid {
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.85rem;
  }

  .schedule-table thead th,
  .schedule-table tbody td {
    padding: 0.875rem 1rem;
    font-size: 0.85rem;
  }
}

@media (max-width: 480px) {
  .btn-group {
    flex-direction: column;
    align-items: center;
  }

  .btn-group .btn {
    width: 100%;
  }

  .carousel-slide-inner {
    aspect-ratio: 4/3;
  }
}

