          if (messageEl) {
            messageEl.textContent = '';
            messageEl.className = 'newsletter-message';
          }
        }, 4000);
      });

      input.addEventListener('input', function () {
        input.classList.remove('error');
        if (messageEl) {
          messageEl.textContent = '';
          messageEl.className = 'newsletter-message';
        }
      });
    });
  }

  /* --- Country Selector --- */
  function initCountrySelector() {
