  document.addEventListener('DOMContentLoaded', function () {
    initMobileNav();
    initCarousel();
    initWorkoutToggle();
    initInstructorFilter();
    initFaqAccordion();
    initNewsletter();
    initCountrySelector();
    setActiveNavLink();
